def describe_autonomous_operations_era() -> str:
    lines = [
        "TitanAI Autonomous Operations Era",
        "",
        "This era extends TitanAI from a software and engineering system into a fully autonomous operations civilization capable of running, protecting, scaling, and improving digital ecosystems.",
        "",
    ]
    for capability in AUTONOMOUS_OPERATIONS_CAPABILITIES:
        lines.append(f"- {capability.version} {capability.name} [{capability.category}]")
        lines.append(f"  {capability.purpose}")
    return "\n".join(lines)
